package com.trimtime.appointment;
import com.trimtime.identity.SessionAuthenticationFilter; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/appointments") @PreAuthorize("hasRole('CUSTOMER')") public class AppointmentController { private final AppointmentService service; public AppointmentController(AppointmentService service){this.service=service;} private Long current(){return ((SessionAuthenticationFilter.UserPrincipal)SecurityContextHolder.getContext().getAuthentication().getPrincipal()).id();} @PostMapping public ResponseEntity<AppointmentDtos.Response> book(@Valid @RequestBody AppointmentDtos.CreateRequest input){return ResponseEntity.status(HttpStatus.CREATED).body(AppointmentDtos.Response.from(service.book(current(),input)));} @GetMapping("/mine") public List<AppointmentDtos.Response> mine(){return service.mine(current()).stream().map(AppointmentDtos.Response::from).toList();} }
